59	<div class="app">
60	  <aside>
61	    <h1>Gene expression grapher</h1>
62	    <p class="sub">Type a value or drag a slider. The graph updates as you go.</p>
63	    <div id="params"></div>
64	    <div class="row">
65	      <label class="toggle" style="font-style:normal;font-family:inherit;font-size:14px">
66	        <input type="checkbox" id="fb"> Protein represses its own gene
67	      </label>
68	    </div>
69	    <div id="fbparams" class="feedback" hidden></div>
70	    <div class="buttons">
71	      <button id="reroll" title="Run the stochastic simulation again with new random numbers">New random run</button>
72	      <button id="reset">Reset values</button>
73	      <button id="load" title="A .txt file with one 'name = value' per line, e.g. r = 1">Load from text file</button>
74	      <input type="file" id="file" accept=".txt,text/plain" hidden>
75	    </div>
76	    <div class="row hint" id="loadmsg">File format: one <code>name = value</code> per line, e.g.
77	      <code>r = 1</code>. Names: r, gamma_m, beta, gamma_p, t_max, and for feedback K, n, r_basal.
78	      Lines starting with # are ignored.</div>
79	  </aside>
80	  <main>
81	    <div id="graph"></div>
82	    <div class="readout" id="readout"></div>
83	  </main>
84	</div>
85	<script>
86	// name, label, default, slider min, slider max, slider step, hint, check
87	const PARAMS = [
88	  ["r",       "r",   1,    0, 5,    0.05,  "transcription rate (mRNA made per unit time)"],
89	  ["gamma_m", "γₘ",  0.5,  0.01, 2, 0.01,  "mRNA degradation rate"],
90	  ["beta",    "β",   10,   0, 50,   0.5,   "translation rate (protein per mRNA per unit time)"],
91	  ["gamma_p", "γₚ",  0.05, 0.005, 0.5, 0.005, "protein degradation rate"],
92	  ["t_max",   "t",   300,  10, 2000, 10,   "how long to simulate"],
93	];
94	const FB_PARAMS = [
95	  ["K",       "K",       200, 1, 1000, 1,   "protein level giving half repression"],
96	  ["n",       "n",       2,   0.5, 6, 0.1,  "Hill coefficient (steepness)"],
97	  ["r_basal", "r₀",      0,   0, 1, 0.01,   "leaky rate at full repression (must be < r)"],
98	];
99	
100	const inputs = {};
101	function buildRows(list, container) {
102	  for (const [name, label, def, lo, hi, step, hint] of list) {
103	    const row = document.createElement("div");
104	    row.className = "row";
105	    row.innerHTML = `<div class="top"><label for="in-${name}">${label}</label><span class="eq">=</span>
106	      <input type="number" id="in-${name}" value="${def}" step="any"></div>
107	      <input type="range" min="${lo}" max="${hi}" step="${step}" value="${def}" aria-label="${label} slider">
108	      <div class="hint">${hint}</div>`;
109	    container.appendChild(row);
110	    const num = row.querySelector("input[type=number]");
111	    const slider = row.querySelector("input[type=range]");
112	    num.addEventListener("input", () => { slider.value = num.value; schedule(); });
113	    slider.addEventListener("input", () => { num.value = slider.value; schedule(); });
114	    inputs[name] = { num, slider, row, def };
115	  }
116	}
117	buildRows(PARAMS, document.getElementById("params"));
118	buildRows(FB_PARAMS, document.getElementById("fbparams"));
119	
120	const fb = document.getElementById("fb");
121	fb.addEventListener("change", () => {
122	  document.getElementById("fbparams").hidden = !fb.checked;
123	  schedule();
124	});
125	let seed = 1;
126	document.getElementById("reroll").addEventListener("click", () => { seed = Math.floor(Math.random() * 1e9); schedule(0); });
127	document.getElementById("reset").addEventListener("click", () => {
128	  for (const k in inputs) { inputs[k].num.value = inputs[k].def; inputs[k].slider.value = inputs[k].def; }
129	  schedule(0);
130	});
131	
132	const fileInput = document.getElementById("file");
133	const loadmsg = document.getElementById("loadmsg");
134	document.getElementById("load").addEventListener("click", () => fileInput.click());
135	fileInput.addEventListener("change", async () => {
136	  const file = fileInput.files[0];
137	  fileInput.value = "";  // so choosing the same file again still triggers a load
138	  if (!file) return;
139	  let res, data;
140	  try {
141	    res = await fetch("/api/parse-parameters", { method: "POST",
142	      headers: { "Content-Type": "application/json" }, body: JSON.stringify({ text: await file.text() }) });
143	    data = await res.json();
144	  } catch (e) {
145	    loadmsg.innerHTML = `<span class="err">Could not read ${escapeHtml(file.name)}.</span>`;
146	    return;
147	  }
148	  if (!res.ok) {
149	    const msg = data.error || (data.detail && data.detail[0] && data.detail[0].msg) || "Invalid file";
150	    loadmsg.innerHTML = `<span class="err">${escapeHtml(file.name)}: ${escapeHtml(msg)}</span>`;
151	    return;
152	  }
153	  for (const [name, v] of Object.entries(data.values)) {
154	    const slider = inputs[name].slider;
155	    // widen the slider if the file's value is outside its range (e.g. the paper's
156	    // rates in per-second units are far smaller than the default slider range)
157	    if (v < Number(slider.min)) { slider.min = v; slider.step = "any"; }
158	    if (v > Number(slider.max)) { slider.max = v; slider.step = "any"; }
159	    inputs[name].num.value = v;
160	    slider.value = v;
161	  }
162	  if (data.feedback) { fb.checked = true; document.getElementById("fbparams").hidden = false; }
163	  loadmsg.textContent = `Loaded ${Object.keys(data.values).length} value(s) from ${file.name}: ` +
164	    Object.entries(data.values).map(([k, v]) => `${k} = ${v}`).join(", ");
165	  schedule(0);
166	});
167	
168	function escapeHtml(t) {
169	  return String(t).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
170	}
171	
172	const css = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
173	const readout = document.getElementById("readout");
174	
175	let timer = null, requestId = 0;
176	function schedule(delay = 200) { clearTimeout(timer); timer = setTimeout(update, delay); }
177	
178	function value(name) {
179	  const t = inputs[name].num.value.trim();
180	  return t === "" ? NaN : Number(t);
181	}
182	
183	async function update() {
184	  const body = { seed, n_points: 1001 };
185	  let ok = true;
186	  const used = PARAMS.map(p => p[0]).concat(fb.checked ? FB_PARAMS.map(p => p[0]) : []);
187	  for (const k in inputs) inputs[k].row.classList.remove("bad");
188	  for (const name of used) {
189	    if (!Number.isFinite(value(name))) { inputs[name].row.classList.add("bad"); ok = false; }
190	  }
191	  if (!ok) { readout.innerHTML = `<span class="err">Enter a number in every box.</span>`; return; }
192	  for (const [name] of PARAMS) body[name] = value(name);
193	  if (fb.checked) body.autorepression = { K: value("K"), n: value("n"), r_basal: value("r_basal") };
194	
195	  const id = ++requestId;
196	  let res, data;
197	  try {
198	    res = await fetch("/api/time-course", { method: "POST",
199	      headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
200	    data = await res.json();
201	  } catch (e) {
202	    if (id === requestId) readout.innerHTML = `<span class="err">Could not reach the server.</span>`;
203	    return;
204	  }
205	  if (id !== requestId) return; // a newer request has been sent; ignore this one
206	  if (!res.ok) {
207	    const msg = data.error || (data.detail && data.detail[0] && data.detail[0].msg) || "Invalid input";
208	    readout.innerHTML = `<span class="err">${escapeHtml(msg)}</span>`;
209	    return;
210	  }
211	  draw(data, body);
212	}
213	
214	function draw(d, body) {
215	  const protein = css("--protein"), mrna = css("--mrna"), text = css("--text"),
216	        muted = css("--muted"), grid = css("--border");
217	  const traces = [
218	    { x: d.t, y: d.p, name: "protein p (simulated)", mode: "lines", line: { color: protein, width: 1.2, shape: "hv" } },
219	    { x: d.t, y: d.det_p, name: "protein p (average)", mode: "lines", line: { color: protein, width: 2.5, dash: "dash" } },
220	    { x: d.t, y: d.m, name: "mRNA m (simulated)", mode: "lines", yaxis: "y2", line: { color: mrna, width: 1, shape: "hv" }, opacity: 0.7 },
221	    { x: d.t, y: d.det_m, name: "mRNA m (average)", mode: "lines", yaxis: "y2", line: { color: mrna, width: 2, dash: "dash" } },
222	  ];
223	  const axis = { gridcolor: grid, zerolinecolor: grid, linecolor: grid, color: muted };
224	  const layout = {
225	    paper_bgcolor: "rgba(0,0,0,0)", plot_bgcolor: "rgba(0,0,0,0)", font: { color: text },
226	    margin: { l: 60, r: 60, t: 20, b: 50 },
227	    xaxis: { ...axis, title: "time" },
228	    yaxis: { ...axis, title: { text: "protein molecules", font: { color: protein } }, rangemode: "tozero" },
229	    yaxis2: { ...axis, title: { text: "mRNA molecules", font: { color: mrna } }, overlaying: "y", side: "right",
230	              rangemode: "tozero", showgrid: false },
231	    legend: { orientation: "h", y: 1.02, yanchor: "bottom", x: 0 },
232	    hovermode: "x unified",
233	  };
234	  Plotly.react("graph", traces, layout, { responsive: true, displaylogo: false });
235	
236	  const fmt = v => v == null ? "—" : (Math.abs(v) >= 100 ? v.toFixed(0) : v.toPrecision(3));
237	  if (d.theory) {
238	    readout.innerHTML = `Steady state: <span>mean mRNA <b>${fmt(d.theory.mean_m)}</b></span>
239	      <span>mean protein <b>${fmt(d.theory.mean_p)}</b></span>
240	      <span>protein noise (Fano = variance/mean) <b>${fmt(d.theory.fano_p)}</b> = 1 + β/(γₘ+γₚ)</span>`;
241	  } else {
242	    readout.innerHTML = `With feedback: average protein settles at <b>${fmt(d.det_p[d.det_p.length - 1])}</b>
243	      (no closed-form noise formula; compare the wiggles to the run without feedback)`;
244	  }
245	}
246	
247	update();
248	</script>
249	</body>
250	</html>
