<body>
<div class="app">
  <aside>
    <h1>Gene expression grapher</h1>
    <p class="sub">Type a value or drag a slider. The graph updates as you go.</p>
    <div id="params"></div>
    <div class="row">
      <label class="toggle" style="font-style:normal;font-family:inherit;font-size:14px">
        <input type="checkbox" id="fb"> Protein represses its own gene
      </label>
    </div>
    <div id="fbparams" class="feedback" hidden></div>
    <div class="buttons">
      <button id="reroll" title="Run the stochastic simulation again with new random numbers">New random run</button>
      <button id="reset">Reset values</button>
      <button id="load" title="A .txt file with one 'name = value' per line, e.g. r = 1">Load from text file</button>
      <input type="file" id="file" accept=".txt,text/plain" hidden>
    </div>
    <div class="row hint" id="loadmsg">File format: one <code>name = value</code> per line, e.g.
      <code>r = 1</code>. Names: r, gamma_m, beta, gamma_p, t_max, and for feedback K, n, r_basal.
      Lines starting with # are ignored.</div>
  </aside>
  <main>
    <div id="graph"></div>
    <div class="readout" id="readout"></div>
  </main>
</div>
<script>
// name, label, default, slider min, slider max, slider step, hint, check
const PARAMS = [
  ["r",       "r",   1,    0, 5,    0.05,  "transcription rate (mRNA made per unit time)"],
  ["gamma_m", "γₘ",  0.5,  0.01, 2, 0.01,  "mRNA degradation rate"],
  ["beta",    "β",   10,   0, 50,   0.5,   "translation rate (protein per mRNA per unit time)"],
  ["gamma_p", "γₚ",  0.05, 0.005, 0.5, 0.005, "protein degradation rate"],
  ["t_max",   "t",   300,  10, 2000, 10,   "how long to simulate"],
];
const FB_PARAMS = [
  ["K",       "K",       200, 1, 1000, 1,   "protein level giving half repression"],
  ["n",       "n",       2,   0.5, 6, 0.1,  "Hill coefficient (steepness)"],
  ["r_basal", "r₀",      0,   0, 1, 0.01,   "leaky rate at full repression (must be < r)"],
];

const inputs = {};
function buildRows(list, container) {
  for (const [name, label, def, lo, hi, step, hint] of list) {
    const row = document.createElement("div");
    row.className = "row";
    row.innerHTML = `<div class="top"><label for="in-${name}">${label}</label><span class="eq">=</span>
      <input type="number" id="in-${name}" value="${def}" step="any"></div>
      <input type="range" min="${lo}" max="${hi}" step="${step}" value="${def}" aria-label="${label} slider">
      <div class="hint">${hint}</div>`;
    container.appendChild(row);
    const num = row.querySelector("input[type=number]");
    const slider = row.querySelector("input[type=range]");
    num.addEventListener("input", () => { slider.value = num.value; schedule(); });
    slider.addEventListener("input", () => { num.value = slider.value; schedule(); });
    inputs[name] = { num, slider, row, def };
  }
}
buildRows(PARAMS, document.getElementById("params"));
buildRows(FB_PARAMS, document.getElementById("fbparams"));

const fb = document.getElementById("fb");
fb.addEventListener("change", () => {
  document.getElementById("fbparams").hidden = !fb.checked;
  schedule();
});
let seed = 1;
document.getElementById("reroll").addEventListener("click", () => { seed = Math.floor(Math.random() * 1e9); schedule(0); });
document.getElementById("reset").addEventListener("click", () => {
  for (const k in inputs) { inputs[k].num.value = inputs[k].def; inputs[k].slider.value = inputs[k].def; }
  schedule(0);
});

const fileInput = document.getElementById("file");
const loadmsg = document.getElementById("loadmsg");
document.getElementById("load").addEventListener("click", () => fileInput.click());
fileInput.addEventListener("change", async () => {
  const file = fileInput.files[0];
  fileInput.value = "";  // so choosing the same file again still triggers a load
  if (!file) return;
  let res, data;
  try {
    res = await fetch("/api/parse-parameters", { method: "POST",
      headers: { "Content-Type": "application/json" }, body: JSON.stringify({ text: await file.text() }) });
    data = await res.json();
  } catch (e) {
    loadmsg.innerHTML = `<span class="err">Could not read ${escapeHtml(file.name)}.</span>`;
    return;
  }
  if (!res.ok) {
    const msg = data.error || (data.detail && data.detail[0] && data.detail[0].msg) || "Invalid file";
    loadmsg.innerHTML = `<span class="err">${escapeHtml(file.name)}: ${escapeHtml(msg)}</span>`;
    return;
  }
