    const n = k.noise ? ` — Fano ${fmt(k.noise.fano.simulated)} (paper ${fmt(k.noise.fano.paper)})` : "";
    return `<div><span class="swatch" style="background:${k.color}"></span>${escapeHtml(describe(k.body))}${n}</div>`;
  }).join("");
}

// ---------- drawing ----------

function draw() {
  if (!current) return;
  const d = current.data;
  const protein = css("--protein"), mrna = css("--mrna"), text = css("--text"),
        muted = css("--muted"), grid = css("--border");
  const traces = [];
  kept.forEach((k, i) => {
    traces.push(
      { x: k.data.t, y: k.data.p, name: `kept ${i + 1} (simulated)`, legendgroup: `k${i}`, mode: "lines",
        line: { color: k.color, width: 1, shape: "hv" }, opacity: 0.8, hovertext: k.label },
      { x: k.data.t, y: k.data.det_p, name: `kept ${i + 1} (average)`, legendgroup: `k${i}`, mode: "lines",
        line: { color: k.color, width: 2, dash: "dash" }, showlegend: false });
  });
  const compare = kept.length > 0;
  traces.push(
    { x: d.t, y: d.p, name: "protein p (simulated)", mode: "lines", line: { color: protein, width: 1.2, shape: "hv" } },
    { x: d.t, y: d.det_p, name: "protein p (average)", mode: "lines", line: { color: protein, width: 2.5, dash: "dash" } });
  if (!compare) {  // mRNA is hidden in compare mode to keep the picture readable
    traces.push(
      { x: d.t, y: d.m, name: "mRNA m (simulated)", mode: "lines", yaxis: "y2", line: { color: mrna, width: 1, shape: "hv" }, opacity: 0.7 },
      { x: d.t, y: d.det_m, name: "mRNA m (average)", mode: "lines", yaxis: "y2", line: { color: mrna, width: 2, dash: "dash" } });
  }
  const axis = { gridcolor: grid, zerolinecolor: grid, linecolor: grid, color: muted };
  const layout = {
    paper_bgcolor: "rgba(0,0,0,0)", plot_bgcolor: "rgba(0,0,0,0)", font: { color: text },
    margin: { l: 60, r: 60, t: 20, b: 50 },
    xaxis: { ...axis, title: "time" },
    yaxis: { ...axis, title: { text: "protein molecules", font: { color: protein } }, rangemode: "tozero" },
    legend: { orientation: "h", y: 1.02, yanchor: "bottom", x: 0 },
    hovermode: "x unified",
  };
  if (!compare) {
    layout.yaxis2 = { ...axis, title: { text: "mRNA molecules", font: { color: mrna } }, overlaying: "y",
                      side: "right", rangemode: "tozero", showgrid: false };
  }
  Plotly.react("graph", traces, layout, { responsive: true, displaylogo: false });
}

'''+s[end:]
